    folder = settings.data_dir / {1: "contracts", 2: "contracts_batch2", 3: "real/cuad", 4: "real/german"}.get(batch, "contracts")
    paths = sorted(p for p in folder.iterdir() if p.suffix.lower() in (".pdf", ".jpg", ".jpeg", ".png"))
