    }
  }
  const retry = async () => {
    try {
      await api.retryDocument(id)
      refresh()
    } catch (e) {
      setErr(String(e))
    }
  }
  const remove = async () => {
    if (!window.confirm(t('delete_confirm'))) return
    try {
      await api.deleteDocument(id)
      navigate('/')
    } catch (e) {
      setErr(String(e))
    }
  }
  const file = async () => {
    try {
