      {ready && (
        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: 'minmax(0,1fr) 300px' }, gap: 3, alignItems: 'start' }}>
          {/* ---------------------------------------------------------- the pages */}
