export default function Home() {
  const t = useT(T)
  const tc = useT(COMMON)
  const label = useLabel(CONTRACT_TYPES)
  const clauseLabel = useLabel(CLAUSE_TYPES)
  const { lang } = useSettings()
  const toast = useToast()
  const navigate = useNavigate()
