type L = { de: string; en: string }

export const CLAUSE_TYPES: Record<string, L> = {
  term_termination: { de: 'Laufzeit und Kündigung', en: 'Term and termination' },
  fees_payment: { de: 'Vergütung und Zahlung', en: 'Fees and payment' },
